package com.example.e2e.stock;

import com.example.e2e.logging.Outcomes;

/**
 * Metric names of com.example.e2e.stock, in one place: call sites call a member here and never name a metric.
 * Generated by logast (metrics.catalog). Rename or document members freely; logast keeps them and adds new
 * ones at the end.
 */
// logast:metrics-catalog
public final class StockMetrics {
    private StockMetrics() {
    }

    /** stock.events{outcome="completed"} +1. */
    public static void stockEventsCompleted() {
        Outcomes.count("stock.events", "completed");
    }

    /** stock.rejects{outcome="completed"} +1. */
    public static void stockRejectsCompleted() {
        Outcomes.count("stock.rejects", "completed");
    }

    /** Registers this catalog's counters at 0 when the application has started: a series exists before the first event. */
    @org.springframework.stereotype.Component
    static final class Registration implements org.springframework.beans.factory.SmartInitializingSingleton {
        @Override
        public void afterSingletonsInstantiated() {
            Outcomes.register("stock.events", "completed");
            Outcomes.register("stock.rejects", "completed");
        }
    }
}
